// execvp (Vector arguments, Path lookup)
char *const args_v[] = {"ls", "-l", "/tmp", NULL};
execvp(args_v[0], args_v);

// execl (List arguments, Full path required)
// Replaces process with /bin/date
execl("/bin/date", "date", NULL);

// execle (List arguments, Custom Environment provided)
char *const envp[] = {"TERM=xterm", "HOME=/root", NULL};
execle("/usr/bin/env", "env", NULL, envp);

// execve (Underlying syscall: full path, vector, environment)
// execve("/bin/sh", args_v, envp);

